// shadowCopy: INIT -> SHADOW_COPY. Copy the ledger as far as the deployment's
// shadow boundary, and the members as they stood there.
func (r *run) shadowCopy(meta store.Meta) error {
	legacyMax, err := r.legacy().MaxGlobalSeq(r.ctx)
	if err != nil {
		return err
	}
	to := r.cfg().ShadowBoundary
	if legacyMax < to {
		to = legacyMax
	}
	from := r.resumeCursor(meta.Cursor, to)
	if _, err := r.replayRange(from, to); err != nil {
		return err
	}
	want := meta
	want.Phase = string(PhaseShadowCopy)
	want.Cursor = to
	want.Divergence = 0
	return r.finishPhase(meta, want)
}

// putMembersAsOf writes the member rows touched by a batch as they stood at
// its last position, so the destination's members and movements agree with
// each other at every checkpoint.
func (r *run) putMembersAsOf(batch []legacy.Entry, hi int64) error {
	seen := map[string]bool{}
	ids := make([]string, 0, len(batch))
	for _, e := range batch {
		if !seen[e.MemberID] {
			seen[e.MemberID] = true
			ids = append(ids, e.MemberID)
		}
	}
	members, err := r.legacy().MembersAsOf(r.ctx, ids, hi)
	if err != nil {
		return err
	}
	rows := make([]store.Member, 0, len(members))
	for _, m := range members {
		rows = append(rows, store.Member{MemberID: m.MemberID, Tier: m.Tier, BalanceCents: m.BalanceCents,
			Version: m.Version, Deleted: m.Deleted, UpdatedAt: m.UpdatedAt})
	}
	return r.putMembers(rows)
